510	def _get_kernel():
511	    global _KERNEL
512	    if _KERNEL is None:
513	        _KERNEL = _SmallQRKernel()
514	    return _KERNEL
515	
516	
517	def _small_qr(A):
518	    B, n, _ = A.shape
519	    kern = _get_kernel()
520	    # smem budget (floats): n*n + 32 (warp scratch) + n (v)
521	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
522	    tau = torch.zeros((B, n), device=A.device, dtype=torch.float32)
523	    # Enough threads to parallelize the 2D trailing tile; capped at 1024.
524	    if n <= 32:
525	        nthreads = 32
526	    elif n <= 64:
527	        nthreads = 128
528	    else:
529	        nthreads = 512
530	    kern.launch(A.contiguous(), H, tau, B, n, nthreads)
531	    return H, tau
532	
533	
534	# Warps-per-block for qr_tiny. Micro-swept on n=32,B=20: fewer warps/block =>
535	# matrices spread across MORE SMs => less serial-chain contention per SM. wpb=2
536	# (51.3us) ~ wpb=1 (51.4us) << wpb=8 (57us) << wpb=20 (92us, all on 1 SM).
537	import os as _os
538	_TINY_WPB = int(_os.environ.get("QR_TINY_WPB", "2"))
539	
540	
541	def _tiny_qr(A):
542	    B, n, _ = A.shape
543	    kern = _get_kernel()
544	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
545	    # The kernel writes taub[k] for every k=0..n-1, so no pre-zeroing memset.
546	    tau = torch.empty((B, n), device=A.device, dtype=torch.float32)
547	    kern.launch_tiny(A.contiguous(), H, tau, B, n, _TINY_WPB)
548	    return H, tau
549	
550	
551	def _block_qr(A):
552	    B, n, _ = A.shape
553	    kern = _get_kernel()
554	    H = torch.empty((B, n, n), device=A.device, dtype=torch.float32)
555	    tau = torch.zeros((B, n), device=A.device, dtype=torch.float32)
556	    nthreads = ((n + 31) // 32) * 32     # one thread per column, warp-rounded
557	    kern.launch_block(A.contiguous(), H, tau, B, n, nthreads)
558	    return H, tau
