cat > /tmp/new_panel.cu << 'KERNEL_EOF'
// ---------------------------------------------------------------------------
// qr_panel: ONE BLOCK per matrix factors ONE column-panel of the batch-major
// blocked-Householder QR (replaces the Triton _panel_factor_kernel, whose
// (MAXH x BLK) register tile spilled at 255 regs/thread -> 2-block occupancy).
//
// REGISTER-BLOCKED design: each thread owns a STRIDED set of panel rows
// (r = tid, tid+NT, ...), holding all b<=BLK<=32 column values of each owned row
// in REGISTERS (areg[ROWS_MAX][32]).  More threads => fewer rows/thread =>
// fewer registers => high occupancy (the opposite of Triton's shared-tile, where
// more warps inflate the per-warp tile).  Each serial reflector step:
//   (1) tail2: per-thread register partial -> intra-warp __shfl reduce -> ONE
//       cross-warp smem+__syncthreads.
//   (2) build v in registers + publish to smem sv[] (one barrier).
//   (3) w[c]=v.panel[:,c] for all c: per-thread REGISTER partials (32 lanes
//       reduce their owned rows) -> __shfl reduce -> cross-warp accumulate of
//       only (32 x nwarps) smem values (vs O(32*pheight) in a smem-resident
//       panel).  This is the barrier/round-trip reduction the brief targets.
//   (4) incremental WY T column (dlarft).
//   (5) rank-1 trailing-panel update in REGISTERS (no smem).
//
// Outputs bit-identical to _panel_factor_kernel (LAPACK dlarfg / dlarft):
//   * Hb panel A[j:j+pheight, j:j+b]: R on/above diag, reflectors below.
//   * tau[bid, j:j+b]  (== T diagonal).
//   * Vbuf[bid] (BLK x N): Vt[c,r] = 1 if r==c, panel[r,c] if r>c, else 0.
//   * Tbuf[bid] (BLK x BLK): forward WY T factor.
// Panel-local row r (0..pheight-1) = global row j+r; col c (0..b-1) = global j+c.
// ROWS_MAX caps owned rows/thread; launcher must pick NT s.t. ceil(pheight/NT)
// <= ROWS_MAX.
// ---------------------------------------------------------------------------
extern "C" __global__ void qr_panel(
    float* __restrict__ A,            // (B, N, N) row-major, factored in place
    float* __restrict__ tau,          // (B, N)
    float* __restrict__ Vbuf,         // (B, BLK, N)
    float* __restrict__ Tbuf,         // (B, BLK, BLK)
    int B, int N, int j, int pheight, int b, int BLK)
{
    const int ROWS_MAX = 4;
    const int BLKC = 32;                      // compile-time column cap (b<=32)
    const int bid = blockIdx.x;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int NT = blockDim.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int nwarps = (NT + 31) >> 5;
    const unsigned FULL = 0xffffffffu;

    extern __shared__ float smem_p[];
    float* sv   = smem_p;                     // reflector v[0..pheight-1]
    float* sw   = sv + pheight;               // w[c], c in [0,BLKC)
    float* swp  = sw + BLKC;                  // cross-warp w partials [nwarps*BLKC]
    float* sred = swp + (long)nwarps * BLKC;  // tail2 partials [nwarps]
    float* ssc  = sred + ((nwarps + 31) & ~31);  // scalars [4]

    float* Ab = A + (long)bid * N * N;

    // Load owned rows into registers: areg[i][c] = A[j + (tid+i*NT), j + c].
    float areg[ROWS_MAX][BLKC];
    int myrows[ROWS_MAX];
    #pragma unroll
    for (int i = 0; i < ROWS_MAX; ++i) {
        int r = tid + i * NT;
        myrows[i] = r;
        if (r < pheight) {
            const float* arow = Ab + (long)(j + r) * N + j;
            #pragma unroll
            for (int c = 0; c < BLKC; ++c)
                if (c < b) areg[i][c] = arow[c];
        }
    }

    for (int k = 0; k < b; ++k) {
        // --- (1) tail2 = sum_{r>k} A[r,k]^2 ---
        float part = 0.0f;
        #pragma unroll
        for (int i = 0; i < ROWS_MAX; ++i) {
            int r = myrows[i];
            if (r > k && r < pheight) { float x = areg[i][k]; part += x * x; }
        }
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            part += __shfl_down_sync(FULL, part, off);
        if (lane == 0) sred[warp] = part;
        __syncthreads();
        if (tid == 0) {
            float tail2 = 0.0f;
            for (int w = 0; w < nwarps; ++w) tail2 += sred[w];
            ssc[1] = tail2;
        }
        __syncthreads();
        float tail2 = ssc[1];

        // alpha = A[k,k] lives in the thread owning row k. Broadcast via ssc.
        if (tid % NT == (k % NT)) { /* placeholder */ }
        // owner of row k: tid == k (since row k = tid + i*NT with i=0 only if k<NT)
        // Generally row k is owned by thread (k % NT) at i = k / NT.
        int owner = k % NT;
        int owner_i = k / NT;
        if (tid == owner) ssc[2] = areg[owner_i][k];   // alpha
        __syncthreads();
        float alpha = ssc[2];

        float beta, tau_k, scale;
        int has_refl;
        if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; has_refl = 0; }
        else {
            float normx = sqrtf(alpha * alpha + tail2);
            float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
            beta = -sgn * normx;
            tau_k = (beta - alpha) / beta;
            scale = 1.0f / (alpha - beta);
            has_refl = 1;
        }

        // --- (2) build v: diag<-1 (sv), col k diag<-beta; below: v=A[r,k]*scale
        if (tid == owner) {
            sv[k] = 1.0f;
            areg[owner_i][k] = has_refl ? beta : alpha;   // R diagonal in place
        }
        #pragma unroll
        for (int i = 0; i < ROWS_MAX; ++i) {
            int r = myrows[i];
            if (r > k && r < pheight) {
                float vr = has_refl ? (areg[i][k] * scale) : 0.0f;
                areg[i][k] = vr;
                sv[r] = vr;
            }
        }
        __syncthreads();

        // --- (3) w[c] = sum_{r>=k} v[r]*A[r,c] for c in [0,b) ---
        // per-thread register partials over owned rows (v[k]=1 via sv[k]).
        float wpart[BLKC];
        #pragma unroll
        for (int c = 0; c < BLKC; ++c) wpart[c] = 0.0f;
        #pragma unroll
        for (int i = 0; i < ROWS_MAX; ++i) {
            int r = myrows[i];
            if (r >= k && r < pheight) {
                float vr = sv[r];
                #pragma unroll
                for (int c = 0; c < BLKC; ++c)
                    if (c < b) wpart[c] += vr * areg[i][c];
            }
        }
        // intra-warp reduce each column partial
        #pragma unroll
        for (int c = 0; c < BLKC; ++c) {
            float v = wpart[c];
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                v += __shfl_down_sync(FULL, v, off);
            if (lane == 0) swp[(long)warp * BLKC + c] = v;
        }
        __syncthreads();
        // cross-warp accumulate: thread c (c<b) sums nwarps partials -> sw[c]
        for (int c = tid; c < b; c += NT) {
            float acc = 0.0f;
            for (int w = 0; w < nwarps; ++w) acc += swp[(long)w * BLKC + c];
            sw[c] = acc;
        }
        __syncthreads();

        // --- (4) incremental T column k (dlarft): Tbuf row-major BLK x BLK ---
        float* Tb = Tbuf + (long)bid * BLK * BLK;
        for (int a = tid; a <= k; a += NT) {
            if (a == k) Tb[(long)a * BLK + k] = tau_k;
            else {
                float s = 0.0f;
                for (int c = 0; c < k; ++c) s += Tb[(long)a * BLK + c] * sw[c];
                Tb[(long)a * BLK + k] = -tau_k * s;
            }
        }

        // --- (5) rank-1 trailing-panel update: A[r,c] -= tau*v[r]*w[c], c>k ---
        if (has_refl) {
            #pragma unroll
            for (int i = 0; i < ROWS_MAX; ++i) {
                int r = myrows[i];
                if (r >= k && r < pheight) {
                    float tv = tau_k * sv[r];
                    #pragma unroll
                    for (int c = 0; c < BLKC; ++c)
                        if (c > k && c < b) areg[i][c] -= tv * sw[c];
                }
            }
        }
        __syncthreads();   // protect sv/sw/swp reuse next step
    }

    // --- write tau (T diagonal) ---
    {
        float* Tb = Tbuf + (long)bid * BLK * BLK;
        for (int c = tid; c < b; c += NT)
            tau[(long)bid * N + (j + c)] = Tb[(long)c * BLK + c];
    }
    // --- zero strictly-lower active T block (a>c) to match Triton Tmat ---
    {
        float* Tb = Tbuf + (long)bid * BLK * BLK;
        for (long idx = tid; idx < (long)b * b; idx += NT) {
            int a = idx / b; int c = idx - (long)a * b;
            if (a > c) Tb[(long)a * BLK + c] = 0.0f;
        }
    }

    // --- write factored panel back to A AND Vt to Vbuf (from registers) ---
    float* Vb = Vbuf + (long)bid * BLK * N;
    #pragma unroll
    for (int i = 0; i < ROWS_MAX; ++i) {
        int r = myrows[i];
        if (r < pheight) {
            float* arow = Ab + (long)(j + r) * N + j;
            #pragma unroll
            for (int c = 0; c < BLKC; ++c) {
                if (c < b) {
                    float val = areg[i][c];
                    arow[c] = val;                       // H panel
                    // Vt[c,r] = 1 if r==c, val if r>c, else 0
                    float vv = (r == c) ? 1.0f : ((r > c) ? val : 0.0f);
                    Vb[(long)c * N + r] = vv;
                }
            }
        }
    }
}
KERNEL_EOF
