// owner of panel-local row k = thread (k % NT) at register slot (k / NT).
float* Tb = Tbuf + (long)bid * BLK * BLK;

for (int k = 0; k < b; ++k) {
    const int owner = k % NT;
    const int owner_i = k / NT;

    // --- tail2 partial (registers) + alpha publish, ONE barrier (B1) ---
    float part = 0.0f;
    #pragma unroll
    for (int i = 0; i < ROWS_MAX; ++i) {
        int r = myrows[i];
        if (r > k && r < pheight) { float x = areg[i][k]; part += x * x; }
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        part += __shfl_down_sync(FULL, part, off);
    if (lane == 0) sred[warp] = part;
    if (tid == owner) sred[nwarps] = areg[owner_i][k];   // alpha
    __syncthreads();                                     // B1

    // every thread redundantly forms the reflector scalars (no barrier)
    float tail2 = 0.0f;
    for (int w = 0; w < nwarps; ++w) tail2 += sred[w];
    float alpha = sred[nwarps];
    float beta, tau_k, scale;
    int has_refl;
    if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; has_refl = 0; }
    else {
        float normx = sqrtf(alpha * alpha + tail2);
        float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
        beta = -sgn * normx;
        tau_k = (beta - alpha) / beta;
        scale = 1.0f / (alpha - beta);
        has_refl = 1;
    }

    // --- build v into registers + publish sv[], ONE barrier (B2) ---
    if (tid == owner) {
        sv[k] = 1.0f;
        areg[owner_i][k] = has_refl ? beta : alpha;   // R diagonal in place
    }
    #pragma unroll
    for (int i = 0; i < ROWS_MAX; ++i) {
        int r = myrows[i];
        if (r > k && r < pheight) {
            float vr = has_refl ? (areg[i][k] * scale) : 0.0f;
            areg[i][k] = vr;
            sv[r] = vr;
        }
    }
    __syncthreads();                                  // B2

    // --- w[c] = sum_{r>=k} v[r]*A[r,c]: register partials, ONE barrier (B3)
    float wpart[BLKC];
    #pragma unroll
    for (int c = 0; c < BLKC; ++c) wpart[c] = 0.0f;
    #pragma unroll
    for (int i = 0; i < ROWS_MAX; ++i) {
        int r = myrows[i];
        if (r >= k && r < pheight) {
            float vr = sv[r];
            #pragma unroll
            for (int c = 0; c < BLKC; ++c)
                if (c < b) wpart[c] += vr * areg[i][c];
        }
    }
    #pragma unroll
    for (int c = 0; c < BLKC; ++c) {
        float v = wpart[c];
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            v += __shfl_down_sync(FULL, v, off);
        if (lane == 0) swp[(long)warp * BLKC + c] = v;
    }
    __syncthreads();                                  // B3

    // every thread redundantly forms the FULL w[] (registers, no barrier)
    float wfull[BLKC];
    #pragma unroll
    for (int c = 0; c < BLKC; ++c) {
        float acc = 0.0f;
        if (c < b)
            for (int w = 0; w < nwarps; ++w) acc += swp[(long)w * BLKC + c];
        wfull[c] = acc;
    }

    // --- incremental WY T column k (dlarft) from wfull ---
    for (int a = tid; a <= k; a += NT) {
        if (a == k) Tb[(long)a * BLK + k] = tau_k;
        else {
            float s = 0.0f;
            for (int c = 0; c < k; ++c) s += Tb[(long)a * BLK + c] * wfull[c];
            Tb[(long)a * BLK + k] = -tau_k * s;
        }
    }

    // --- rank-1 trailing-panel update in registers: A[r,c]-=tau*v[r]*w[c]
    if (has_refl) {
        #pragma unroll
        for (int i = 0; i < ROWS_MAX; ++i) {
            int r = myrows[i];
            if (r >= k && r < pheight) {
                float tv = tau_k * sv[r];
                #pragma unroll
                for (int c = 0; c < BLKC; ++c)
                    if (c > k && c < b) areg[i][c] -= tv * wfull[c];
            }
        }
    }
    __syncthreads();   // end-of-step: protect sv/swp/sred before reuse
}

